":root {
    /* Paleta Oficial IMC - Indoor Media Control (extraída do logotipo e do imc-server) */
    --imc-bg-deep: #0b0e17;
    --imc-bg-dark: #0f111a;
    --imc-bg-card: #161925;
    --imc-bg-card-hover: #1c2030;
    --imc-border: #1f263b;
    --imc-border-glow: rgba(28, 132, 215, 0.38);

    /* Tons de Azul do Logotipo IMC (#0c4a78 -> #1c84d7 -> #38bdf8) */
    --imc-blue-navy: #0b4a7a;
    --imc-blue-primary: #1565c0;
    --imc-blue-electric: #1c84d7;
    --imc-blue-accent: #4364f7;
    --imc-cyan: #38bdf8;

    --imc-text-main: #f8fafc;
    --imc-text-muted: #94a3b8;
    --imc-text-dim: #64748b;

    --imc-success: #10b981;
    --imc-warning: #f59e0b;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    scroll-behavior: smooth;
}

body {
    background-color: var(--imc-bg-deep);
    color: var(--imc-text-main);
    font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
    line-height: 1.6;
    overflow-x: hidden;
    position: relative;
}

/* Fundo Tecnológico com Grid e Glow Radial do Logotipo */
.bg-ambient-grid {
    position: fixed;
    inset: 0;
    z-index: -2;
    background-image:
        radial-gradient(circle at 18% 15%, rgba(28, 132, 215, 0.16) 0%, transparent 45%),
        radial-gradient(circle at 82% 28%, rgba(67, 100, 247, 0.14) 0%, transparent 45%),
        radial-gradient(circle at 50% 85%, rgba(11, 74, 122, 0.2) 0%, transparent 55%),
        linear-gradient(rgba(255, 255, 255, 0.022) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, 0.022) 1px, transparent 1px);
    background-size: 100% 100%, 100% 100%, 100% 100%, 48px 48px, 48px 48px;
    pointer-events: none;
}

/* Navbar */
.imc-navbar {
    background: rgba(11, 14, 23, 0.84);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border-bottom: 1px solid rgba(255, 255, 255, 0.07);
    padding: 0.85rem 0;
    transition: all 0.25s ease;
}

